def minSubArraySum(nums):
    if not nums:
        return 0

    current_min = nums[0]
    min_so_far = nums[0]

    for i in range(1, len(nums)):
        # Standard Kadane's algorithm modified to find the minimum subarray sum
        current_min = min(nums[i], current_min + nums[i])
        if current_min < min_so_far:
            min_so_far = current_min

    return min_so_far

