def minPath(grid, k):
    n = len(grid)
    # Find the starting position of value 1 (the smallest possible start for lexicographical order)
    r, c = -1, -1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                r, c = i, j
                break
        if r != -1: break

    path = [grid[r][c]]
    # Greedily pick the smallest neighbor at each step to ensure lexicographical minimality
    for _ in range(k - 1):
        best_val = float('inf')
        next_pos = (r, c)
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if grid[nr][nc] < best_val:
                    best_val = grid[nr][nc]
                    next_pos = (nr, nc)
        r, c = next_pos
        path.append(grid[r][c])

    return path
